    'the_secret_signs_every_delivery_s_hmac_it_is_stored_sea_830c30dd' => 'El secreto firma el HMAC de cada entrega. Se almacena cifrado y no puede recuperarse. Al renovarlo se emite uno nuevo, mostrado una vez.',
    'the_sign_in_page_your_people_see_is_yours_not_ours_logo_7573e3bf' => 'La página de inicio de sesión usa tu logotipo, tus colores y tus textos. Los cambios se previsualizan al instante y se aplican al acceso alojado de esta organización.',
    'the_site_your_account_lives_on_the_domain_of_the_datado_7f128cbf' => 'El sitio de Datadog donde está tu cuenta: el dominio de la URL en la que inicias sesión. Una clave API solo funciona en su propio sitio.',
    'the_teams_using_your_product_each_is_a_company_or_group_91579359' => 'Los equipos que usan tu producto. Cada organización es una empresa o grupo con sus propios usuarios, roles e inicio de sesión único.',
    'the_token_your_identity_provider_currently_holds_stops_5458b580' => 'El token que tiene actualmente tu proveedor de identidad deja de funcionar de inmediato. El aprovisionamiento falla hasta que pegues allí el nuevo.',
    'this_transfers_ownership_of_the_shared_organization_rol_19e09a02' => 'Esto transfiere la propiedad de la organización compartida. Los roles de cada aplicación no cambian; podrías perder el acceso a Cbox ID.',
    'they_lose_access_to_this_organization_and_everything_it_984eedd8' => 'La persona pierde el acceso a esta organización y todos los derechos que concede. Su cuenta no cambia.',
    'they_lose_this_role_in_every_organization_at_once_apps_2750f7e3' => 'Pierden este rol en todas las organizaciones a la vez. Las comprobaciones de autorización en tiempo real reflejan el cambio en la siguiente acción protegida; las declaraciones de los tokens existentes son instantáneas. No se cierra ninguna sesión.',
    'they_lose_this_role_in_every_organization_at_once_apps_39477fda' => 'Pierden este rol en todas las organizaciones a la vez. Las comprobaciones de autorización en tiempo real reflejan el cambio en la siguiente acción protegida; las declaraciones de los tokens existentes son instantáneas. No se cierra ninguna sesión.',
    'this_app_belongs_to_the_platform_and_is_available_to_ev_0c69cd5f' => 'Esta aplicación pertenece a la plataforma y está disponible para todas las organizaciones del entorno. La gestiona tu operador.',
    'this_app_signs_assertions_with_its_own_keys_and_has_no_7e457dd4' => 'Esta aplicación firma aserciones con sus propias claves y no tiene secreto. Renueva la clave en su JWKS.',
    'this_changes_permissions_for_all_current_holders_of_thi_a515eb89' => 'Esto cambia los permisos de todas las personas que tienen actualmente este rol. No se asigna el rol a nadie nuevo.',
