    'this_connection_can_t_be_changed_while_the_organization_d78c4f4e' => 'No se puede modificar esta conexión sin el plan Enterprise para la organización. Contacta con tu responsable de cuenta para activarlo.',
    'this_connection_is_missing_its_identity_provider_s_deta_b5943e9d' => 'Faltan los datos del proveedor de identidad de esta conexión. Complétalos antes de activarla.',
    'this_connection_s_settings_could_not_be_read_so_nothing_0ab248ca' => 'No se pudieron leer los ajustes de esta conexión, así que no se cambió nada. Vuelve a introducir primero los ajustes del proveedor de identidad.',
    'this_deployment_does_not_let_an_mcp_client_sign_you_in__2bbe3144' => 'Este despliegue no permite iniciar sesión en el nivel raíz mediante un cliente MCP. Usa la CLI cbox o una clave de organización de abajo.',
    'this_destroys_the_user_s_enrolled_second_factor_and_the_288206be' => 'Esto elimina el segundo factor configurado y los códigos de recuperación del usuario. Hasta que configure otro factor, la cuenta solo queda protegida por la contraseña.',
    'this_domain_will_no_longer_route_its_users_through_this_281a9227' => 'Este dominio dejará de dirigir a sus usuarios al SSO de esta organización. Esta acción no se puede deshacer.',
    'this_endpoint_belongs_to_the_environment_and_receives_e_f1dc8df9' => 'Este endpoint pertenece al entorno y recibe eventos de todas las organizaciones, incluida la tuya. Lo gestiona tu operador.',
    'this_endpoint_stops_receiving_events_and_its_delivery_h_b6a65cf3' => 'Este endpoint deja de recibir eventos y se elimina su historial de entregas. Esta acción no se puede deshacer.',
    'this_environment_falls_back_to_its_default_domain_every_201d6a2d' => 'El entorno vuelve a su dominio predeterminado. Los clientes con emisor, URL de descubrimiento o URL JWKS fijos dejarán de funcionar hasta que se actualicen.',
    'this_idempotency_key_was_already_used_for_a_different_r_0c304fb5' => 'Esta Idempotency-Key ya se usó para otra solicitud. Usa una clave nueva para una solicitud nueva.',
    'this_is_exactly_how_your_sign_in_renders_the_preview_sh_a4878600' => 'Así se muestra realmente tu página de acceso. La vista previa usa el mismo mecanismo de temas que la página real.',
    'this_is_the_app_s_only_live_secret_rotate_it_to_replace_70716789' => 'Este es el único secreto activo de la aplicación. Renuévalo para sustituirlo o elimina la aplicación para desactivarla.',
    'this_is_the_app_s_only_live_secret_so_it_cannot_be_revo_d05986bb' => 'Este es el único secreto activo de la aplicación y no se puede revocar por separado, porque la dejaría sin sustituto. Renuévalo en su lugar.',
    'this_is_your_environment_s_default_sign_in_an_organizat_d17d58dd' => 'Este es el acceso predeterminado del entorno. Una organización puede sustituirlo por su propio tema.',
    'this_organization_owns_identity_provider_projects_on_th_f851615d' => 'Esta organización posee proyectos de proveedores de identidad en esta plataforma y no puede archivarse aquí.',
    'this_organization_owns_identity_providers_on_this_platf_f47c5479' => 'Esta organización posee proveedores de identidad en esta plataforma. Cierra primero sus proyectos en Organización › Proyectos.',
    'this_organization_s_brand_it_overrides_the_environment_ffdddbcc' => 'La marca de esta organización sustituye la predeterminada del entorno. Los cambios se previsualizan al instante y se aplican a su acceso alojado.',
    'this_organization_s_own_authentication_policy_is_droppe_a12f3b55' => 'Se elimina la política de autenticación propia de esta organización. Desde ahora se aplican las reglas base del entorno.',
    'this_permission_is_removed_from_every_role_that_current_d88d6738' => 'Este permiso se elimina de todos los roles que lo conceden actualmente. Esta acción no se puede deshacer.',
    'this_provider_s_discovery_document_publishes_no_signing_07a38178' => 'El documento de descubrimiento de este proveedor no publica claves de firma (jwks_uri). Pega su clave pública PEM de firma de tokens de identidad.',
    'this_role_belongs_to_the_environment_and_applies_across_0a2b2ed6' => 'Este rol pertenece al entorno y se aplica a todas sus organizaciones. Se aplica aquí, pero no puedes modificarlo.',
    'this_role_grants_no_permissions_the_application_that_de_59b043d0' => 'Este rol no concede permisos. La aplicación que lo define controla lo que permite hacer.',
    'this_role_is_declared_by_an_application_which_is_its_so_03e7843e' => 'Este rol lo define una aplicación, que es su fuente de referencia. No se puede editar aquí.',
    'this_rule_binds_every_organization_here_choose_one_in_t_9d1bbde3' => 'Esta regla se aplica a todas las organizaciones. Elige una en la cabecera de la consola para comprobar sus asignaciones.',
    'this_rule_binds_every_organization_in_the_environment_i_91928f48' => 'Esta regla se aplica a todas las organizaciones del entorno. Aparece aquí porque también limita la tuya. La gestiona tu operador.',
    'this_user_is_held_at_a_password_change_they_cannot_reac_ce196382' => 'Este usuario debe cambiar la contraseña. No puede acceder a nada hasta sustituir la que le proporcionaste.',
    'to_register_an_api_for_one_organization_find_it_here_it_48b04329' => 'Para registrar una API para una organización, búscala aquí. Después podrás seleccionarla como propietaria arriba.',
    'user_erased_their_account_is_pseudonymised_and_the_eras_51e1f69a' => 'Usuario borrado. Su cuenta se ha seudonimizado y el borrado se ha registrado como user.erased en el registro de auditoría.',
    'valid_once_and_short_lived_turn_this_off_only_if_you_ar_521114e3' => 'Válido una sola vez y durante poco tiempo. Desactívalo solo si creas la cuenta con antelación y vas a enviar tú el enlace.',
    'verify_that_authnrequests_really_come_from_this_applica_f3c58c70' => 'Verificar que las AuthnRequests proceden realmente de esta aplicación con su propio certificado de firma.',
    'verify_the_domain_before_turning_capture_on_until_then_4ff9f310' => 'Verifica el dominio antes de activar el enrutamiento SSO. Hasta entonces, la organización no ha demostrado que controla esas direcciones.',
    'verify_the_email_domains_you_own_so_your_people_are_rou_3f6d7cfe' => 'Verifica los dominios de correo que posees para dirigir automáticamente a tus usuarios hacia tu proveedor.',
    'verify_the_signature_on_every_call_and_answer_within_th_5219ed81' => 'Verifica la firma de cada llamada y responde antes del tiempo límite: hay una persona esperando en la pantalla de acceso.',
    'we_could_not_send_that_invitation_the_mail_server_refus_81a3f4df' => 'No se pudo enviar la invitación porque el servidor de correo la rechazó. No se creó nada. Reinténtalo o comprueba la configuración de correo del despliegue.',
    'webhook_id_webhook_timestamp_and_webhook_signature_with_73e511b0' => 'webhook-id, webhook-timestamp y webhook-signature con un secreto whsec_, verificables con cualquier biblioteca Standard Webhooks.',
    'what_people_can_do_inside_your_apps_you_assign_roles_he_c31f1a20' => 'Lo que las personas pueden hacer en tus aplicaciones. Asignas los roles aquí y cada aplicación decide qué permiten.',
    'what_this_round_is_called_when_somebody_asks_which_revi_6e0713c0' => 'El nombre de esta ronda cuando alguien pregunte de qué revisión procede una decisión: un trimestre, una auditoría o una fecha.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_789a1199' => 'Todo lo que use esta clave dejará de funcionar de inmediato. Esta acción no se puede deshacer.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_e14495d2' => 'Todo lo que use esta clave dejará de funcionar de inmediato. Avisa antes al titular si puedes. Esta acción no se puede deshacer.',
    'when_an_app_or_agent_needs_your_go_ahead_to_act_as_you_3a85a2a9' => 'Cuando una aplicación o agente necesita tu permiso para actuar en tu nombre, lo solicita aquí. Aprueba solo las solicitudes que hayas iniciado tú.',
    'when_somebody_creates_an_api_key_for_one_of_your_apps_i_15c6370c' => 'Cuando alguien crea una clave API para una de tus aplicaciones, aparece aquí con su titular y sus permisos.',
    'whether_the_background_work_of_this_install_webhooks_si_0647da12' => 'Si realmente se envían las tareas en segundo plano de esta instalación: webhooks, avisos de cierre de sesión a aplicaciones conectadas y correos en cola.',
    'which_headers_every_delivery_carries_changing_it_issues_5a2ff32e' => 'Las cabeceras que incluye cada entrega. Cambiarlas no genera un secreto nuevo: el que tienes firma en ambos casos.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Quién pertenece a esta organización y qué puede hacer. Quienes aún no tienen cuenta reciben una invitación por correo.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Quién recibe el indicador cuando ninguna regla lo menciona. Déjalo desactivado para empezar por organizaciones concretas o un porcentaje de usuarios.',
    'who_is_signed_in_as_them_right_now_why_a_sign_in_was_al_181f0520' => 'Quién tiene una sesión abierta como esa persona ahora. Radar explica por qué un acceso se permitió, requirió verificación o se bloqueó.',
    'whose_people_sign_in_through_it_its_domains_and_admin_p_9c461a3e' => 'La organización cuyos miembros inician sesión mediante esta conexión. Sus dominios y el enlace al portal de administración están en su página.',
    'withdrawn_people_already_migrated_are_unaffected_anyone_228f7b22' => 'Retirado. Las personas ya migradas no se ven afectadas; quienes siguen en el sistema antiguo no pueden iniciar sesión.',
    'organization_suspended_its_members_can_no_longer_sign_i_35d8877a' => 'Organización suspendido. Sus miembros ya no pueden iniciar sesión y sus entornos dejan de ofrecer autenticación.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Crear, reordenar y eliminar reglas de Radar, ajustar las integradas y gestionar las entradas de las listas de permitidos y bloqueados.',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'Eres el único propietario. Transfiere primero la propiedad a otra persona o elimina la organización.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'Puedes volver a «Preferir SSO» o «Ambos disponibles» cuando quieras. Las sesiones cerradas siguen cerradas.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Pierdes de inmediato el acceso a esta organización y sus aplicaciones. Un administrador puede volver a invitarte.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Necesitas las credenciales de tu propia cuenta con el proveedor, normalmente un identificador de cliente y un secreto. Apple emite una clave de firma en su lugar.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'Tu política de autenticación sigue vigente: robustez de contraseñas, comprobación de filtraciones, confirmación del correo, límites de solicitudes y controles contra bots.',
    'your_endpoint_is_called_in_the_middle_of_an_operation_a_ab67a6b0' => 'Tu endpoint se llama durante una operación y su respuesta cambia el resultado, por ejemplo añadiendo datos al token o denegando el acceso.',
    'your_endpoints_get_a_signed_message_after_something_hap_04723db4' => 'Tus endpoints reciben un mensaje firmado tras un evento aquí, para que tus sistemas reaccionen sin consultarnos continuamente.',
    'your_hr_system_people_get_an_account_on_their_start_dat_6be42da6' => 'Tu sistema de recursos humanos: las personas reciben una cuenta en su primer día y pierden el acceso después del último.',
    'your_organization_s_name_domains_and_defaults_changes_h_8e3220c0' => 'El nombre, los dominios y los valores predeterminados de tu organización. Los cambios afectan a todas las personas que acceden a través de ella.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Tu propia API. Decides, ámbito por ámbito, cuáles pueden solicitar las aplicaciones registradas por organizaciones.',
    'your_own_credentials_with_each_provider_offered_on_ever_82ce1e08' => 'Tus propias credenciales de cada proveedor, disponibles en todas las páginas de acceso de este entorno. Todas las organizaciones las heredan.',
    'your_own_credentials_with_each_provider_offered_to_ever_d1715d1a' => 'Tus propias credenciales de cada proveedor, disponibles para todos en este entorno. Cada organización las hereda.',
    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'Tu receptor conserva el mismo secreto y lo usa tal cual, incluido el prefijo whsec_, como clave HMAC para X-Cbox-Signature.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Tu página de acceso lleva tu logotipo y tus colores. Las personas introducen ahí su contraseña, así que debe reconocerse como tuya.',
    'your_organization_its_projects_team_keys_and_billing_si_152a2f42' => 'Tu organización: proyectos, equipo, claves y facturación. El acceso a tus aplicaciones se configura en la consola de cada entorno.',
    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Un indicador de función es un ajuste que tus aplicaciones consultan para una persona en una organización. Actívalo para usuarios u organizaciones concretos o para un porcentaje del total. Todas las aplicaciones reciben la misma respuesta mediante el claim `feature_flags` del token o el endpoint de evaluación, sin otro despliegue. Una regla de usuario prevalece sobre una de organización, después sobre el despliegue gradual y después sobre el valor predeterminado.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Una clave permite a tus scripts e integraciones llamar a la API de una aplicación en tu nombre sin iniciar sesión. Solo puede hacer lo que tú puedes hacer en esa aplicación. Si tus permisos se reducen, los de la clave también. La clave se muestra una sola vez: cópiala al crearla y revócala en cuanto se filtre o deje de usarse.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Un permiso permite a un rol realizar una acción, como crear facturas o leer informes. Puedes definir permisos aquí sin código y agruparlos en roles. Las aplicaciones también pueden registrar los suyos automáticamente para reflejar sus comprobaciones reales. Puedes modificar tus permisos; los compartidos por el entorno se pueden usar, pero no modificar.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Un teléfono con la aplicación de autenticación responde a las solicitudes de aprobación y avisa cuando alguien inicia sesión como tú. Regístralo escaneando el código. Si pierdes el teléfono, elimínalo aquí de inmediato para impedir que apruebe más solicitudes.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'Un proyecto es un producto de proveedor de identidad de esta organización, al que pertenecen sus entornos. Hasta que la organización cree uno desde su consola, no hay nada que seleccionar o abrir aquí. Esta pantalla no crea proyectos en su nombre.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Un proyecto es uno de tus productos, con su propio plan, acceso y entornos, como producción y preproducción. Abre un entorno desde aquí para administrarlo. Crea un proyecto cuando lances un producto que deba funcionar y facturarse de forma independiente.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Un rol es una función que tus aplicaciones entienden, como editor o agente de soporte. Asignas los roles aquí y cada aplicación decide qué permiten. Los roles acompañan a la persona en todas las aplicaciones conectadas, para conceder o retirar acceso desde un solo lugar.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Una revisión permite comprobar quién tiene cada rol y si aún lo necesita. Los permisos se acumulan cuando las personas cambian de equipo y conservan los anteriores. La revisión ayuda a retirarlos. Las revocaciones se aplican al cerrarla y todo queda documentado para la auditoría.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Un esquema describe cómo deben ser los eventos de una acción: sus tipos de destino y sus metadatos. Los eventos con esquema se comprueban al llegar. Sin esquema se aceptan tal como se envían, salvo que esté activado el modo estricto.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Una organización es el área de una empresa registrada en esta instalación, con sus proyectos, entornos y equipo. Ábrelo para administrarlos. Al suspenderlo se cierran las sesiones de sus miembros y se detienen los accesos en todos sus entornos.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Los accesos se acumulan. Las personas cambian de equipo y conservan permisos antiguos hasta que una auditoría pregunta por ellos. Una revisión captura las asignaciones actuales y exige decidir, una por una, si siguen siendo necesarias.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Añade a la persona a una organización de abajo para darle acceso allí. Si tus aplicaciones no tienen separación por clientes, puedes darle un rol de administración y soporte para todo el entorno.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Un rol de administración y soporte se concede a tu personal, como soporte u operaciones, en todo el entorno. Se aplica en cada organización sin que sus administradores puedan verlo, asignarlo o retirarlo. Un rol de aplicación concedido así sigue limitado a esa aplicación.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Un rol de administración y soporte se concede a tu personal en todo el entorno. Se aplica en cada organización y sus administradores no pueden verlo ni modificarlo.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Un agente es software que actúa en este entorno con una clave de gestión: un asistente de IA como Claude Code o Cursor, un bot interno o tu backend. Dale a cada uno su propia clave con solo los ámbitos necesarios. Decide qué acciones requieren tu aprobación y revoca la clave cuando termine o si algo parece sospechoso.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Una API es un servicio tuyo que recibe tokens de acceso, como https://api.example.com. Regístrala con los ámbitos que reconoce. Tú decides cuáles pueden solicitar las aplicaciones registradas por las organizaciones. Un token para esa API incluye su dirección como audiencia, que tu servicio comprueba.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Un entorno es un servicio de identidad totalmente aislado con sus propios usuarios, claves, acceso y emisor. Aquí aparecen todos los de esta instalación con su organización. Crea uno, selecciónalo en la consola y configura su primera organización y administrador.',
    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'Un entorno está totalmente aislado, con sus propios usuarios, claves, acceso y emisor. Crea el primero arriba y después configura una organización y un administrador.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Un proveedor de identidad que importe metadatos del proveedor de servicios usa esta URL en lugar de introducir por separado el identificador de entidad y la URL ACS. Funciona incluso antes de completar los datos del proveedor de identidad.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Una organización reúne usuarios, métodos de acceso y roles. Crea una arriba o configura la primera organización y su administrador desde la pantalla Entornos.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'El proveedor propio de una organización sustituye al del entorno en su página de acceso. También aparecen los proveedores heredados que se han desactivado. Esto solo quita el botón; exigir SSO es lo que impide otros métodos de acceso.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'Las claves API y los tokens que tus aplicaciones y agentes necesitan para otros servicios se guardan cifrados aquí, en lugar de en cada configuración. Guarda un secreto una vez y autoriza a aplicaciones concretas a usarlo. No vuelve a mostrarse: renuévalo si lo pierdes.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Las claves API que tus aplicaciones y agentes usan en otros servicios. Cada valor se guarda cifrado, solo se entrega a aplicaciones autorizadas y no vuelve a mostrarse después de guardarlo.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Aplicaciones que solicitan actuar en nombre de tus usuarios. Cada usuario aprueba sus propias solicitudes. Deniega aquí solo las que parezcan abusivas; la denegación queda en el registro de auditoría.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Las aplicaciones con listas propias de usuarios se desincronizan en cuanto alguien entra o sale. Una conexión SCIM transmite cada cambio al instante, incluidas las bajas, que suelen olvidarse.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID envía un mensaje firmado a tu endpoint después de un evento, como una nueva incorporación o un cambio de rol. Tus sistemas reaccionan sin consultas periódicas. Las entregas se reintentan si hace falta. El endpoint recibe la información después del evento y no puede decidir sobre él.',
    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Confirma los accesos aún necesarios y revoca el resto. Nada se aplica antes de cerrar la revisión. Un rol de administración y soporte revocado se retira entonces de todas las organizaciones a la vez.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Elige SCIM si tu proveedor nos envía los datos, Google Workspace o Entra si debemos obtenerlos, o tu sistema de recursos humanos, como Workday, BambooHR, Rippling, HiBob o Personio, para crear las cuentas en la fecha de incorporación.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code abre tu navegador para iniciar sesión aquí y te pregunta qué autorizas. No hay ninguna clave que guardar. Cualquier cliente MCP con acceso OAuth funciona igual con esta URL.',
    'comma_or_space_separated_a_scope_you_type_is_unowned_it_c5513416' => 'Separa con comas o espacios. Un ámbito escrito no tiene una API propietaria y llega tal cual a los tokens de la aplicación. Nunca puede indicar la audiencia de una API registrada; usa las listas de arriba para eso.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Crear, modificar, activar, desactivar y eliminar conexiones SSO, exigir SSO a una organización y verificar sus dominios de correo y activar su enrutamiento SSO. Cambia cómo inician sesión las personas.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Crea la organización, su propietario, su primer producto y el entorno de producción de ese producto. El propietario recibe por correo un enlace para configurar su contraseña; no eliges una por él.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Definir, sustituir y eliminar esquemas de validación de eventos de auditoría, y modificar su plazo de conservación. Acortar el plazo elimina definitivamente los eventos más antiguos.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Eliminar esta organización elimina todos sus proyectos y entornos. Para proteger los proveedores de identidad activos, esta operación no es de autoservicio. Contacta con soporte para continuar.',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Cada organización es una empresa o equipo que usa tu producto, con sus propios miembros, roles, dominios y SSO. Crea una por cada empresa que se registre. Ábrela para gestionar miembros, invitaciones y dominios verificados, o para suspenderla.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Cada canalización permite conectar una cuenta propia de servicios como GitHub, Google o Slack. Los tokens se guardan cifrados y se mantienen actualizados aquí. Las aplicaciones autorizadas solicitan un token válido cuando llaman al servicio en nombre de la persona, sin almacenarlo ellas mismas.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Cada proyecto de la organización tiene su propio plan y cuota de entornos. Se muestran junto al uso del mes: organizaciones, conexiones SSO facturadas e inicios de sesión. El precio tiene en cuenta los usuarios activos mensuales y las conexiones empresariales como SSO y SCIM. Los entornos de pruebas no generan cargos por conexión.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Todo el entorno: cualquier persona con cuenta en él puede acceder a esta aplicación, sea cual sea su organización. Elige una organización si no es lo que pretendes.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Borrar definitivamente a una persona (RGPD, art. 17): se eliminan credenciales, sesiones, pertenencias y datos personales, y se seudonimiza la cuenta. No se puede deshacer.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Orden de evaluación: lista de bloqueados, lista de permitidos, tus reglas de arriba abajo con decisión en la primera coincidencia y después las integradas, donde decide la más estricta que coincida. Sin coincidencias, se permite el acceso.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Cada acción se acepta tal como la envía la aplicación. Añade un esquema para comprobar sus eventos al llegar. La coherencia del registro se garantiza al escribir el evento, no al leerlo.',
    'every_administrative_change_members_roles_connections_a_ef641619' => 'Cada cambio administrativo en miembros, roles, conexiones o aplicaciones se registra aquí al ocurrir, con su autor y fecha. No requiere configuración.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Las claves API guardadas en configuraciones o archivos de entorno no se pueden renovar centralmente ni retirar con rapidez. Aquí se guardan cifradas, se conceden por aplicación y se revocan con un clic.',
    'every_api_key_the_people_in_this_organization_have_crea_b802c1e7' => 'Todas las claves API creadas por personas de esta organización para sus aplicaciones. Revoca las filtradas o que ya no se usan. Cada persona crea sus claves en Mi cuenta.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Todas las claves API creadas por personas de esta organización: titular, aplicación, permisos y último uso. Una clave no tiene más permisos que su titular y deja de funcionar cuando este se marcha. Revoca las filtradas o sin uso. Cada persona crea las suyas en Mi cuenta.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Cada aplicación que permite acceder mediante Cbox ID o llama a su API se registra aquí y recibe credenciales propias. Registra una por aplicación y entorno. No compartas credenciales entre ellas, para poder revocar una sin afectar a las demás.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Todos los navegadores y dispositivos conectados a tu cuenta, las aplicaciones autorizadas y tus últimos accesos y cambios de seguridad. Si no reconoces algo, cierra la sesión o retira el acceso de la aplicación y después cambia tu contraseña.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Cada cambio en esta organización: quién hizo qué, sobre qué elemento y cuándo. Los hashes de las entradas están encadenados; modificar o eliminar una rompe la cadena y se detecta. El registro es de solo lectura a propósito: es la evidencia que se entrega en una auditoría.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Todas las conexiones entre Cbox ID y otros sistemas en un solo lugar: SSO, acceso social, sincronización de directorios y recursos humanos, aprovisionamiento saliente, aplicaciones SAML, webhooks, hooks, flujos de registros y canalizaciones. Cada tarjeta del catálogo abre su configuración. Conexiones muestra las existentes con su estado, los errores primero.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Todas las organizaciones del entorno seleccionado en la consola, como un árbol de distribuidores, organizaciones gestionadas y subunidades. Crea o suspende una organización, o muévela a otra organización superior.',
    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Todas las páginas que abras desde ahora, como Organizaciones, Uso o el detalle de una organización, leerán este entorno. No se modifica ninguno de los dos entornos.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Todas las personas con identidad en este entorno, sin importar sus organizaciones. Abre una para restablecer contraseña o segundo factor, cerrar sesiones, desactivar la cuenta, cambiar organizaciones y roles o borrarla definitivamente tras una solicitud de supresión.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Todas las revocaciones registradas en esta revisión se aplican ahora. Los elementos sin revisar siguen su política, que revoca el acceso de forma predeterminada. Esta acción no se puede deshacer.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Todos los secretos que permiten autenticar esta aplicación ahora. Solo se guarda un hash de cada uno. La lista muestra los cuatro últimos caracteres para identificar el que usa un despliegue.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Se revocan todos los tokens que emitió y ningún nuevo inicio de sesión puede usarlo. Las aplicaciones que verifican los tokens por sí mismas los aceptan hasta que caduquen, como máximo al terminar la sesión.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Todos los métodos de acceso, con su estado y dónde cambiarlos: contraseña, claves de acceso, enlace por correo, acceso social, Enterprise SSO y segundo factor. El entorno controla la mayoría; cada organización gestiona sus conexiones SSO. Las restricciones del despliegue se indican con el nombre del ajuste correspondiente.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Todos las organizaciones de esta instalación. Abre uno para gestionar sus productos y entornos. Suspenderlo cierra las sesiones de sus miembros y detiene la autenticación en todos sus entornos.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Todas las personas que administran esta organización, su rol integrado (Propietario, Administrador, Desarrollador, Miembro o Lector) y los entornos accesibles. Invita por correo y concede solo los entornos necesarios para cada trabajo.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Todas las personas que pueden acceder a esta organización y tus invitaciones pendientes de aceptar. Invita por correo: cada persona configura su acceso sin que tengas que gestionar su contraseña.',
