    'catalog_search_clients' => 'Buscar integraciones OAuth',
    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Un código puede robarse mediante un cambio fraudulento de SIM o una portabilidad no autorizada, interceptarse en la red telefónica o introducirse en una página de inicio de sesión falsa convincente. Aun así, es mucho más seguro que una contraseña sola. Actívalo para quienes no puedan usar una aplicación de autenticación ni una clave de acceso.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Un logotipo cargado desde otro sitio revelaba a ese sitio quién abría tu página de inicio de sesión. Por eso, las páginas alojadas ahora solo muestran imágenes subidas aquí. Súbelo en :part2, más abajo, o elimínalo para que desaparezca este aviso.',
    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 Un rol es una etiqueta incluida en el token. Los roles declarados por una aplicación son de solo lectura aquí; los demás los defines tú. Cada miembro también tiene exactamente un :part2 :part3 :part4 (propietario, administrador, desarrollador, miembro o lector), que determina qué puede administrar en esta consola.',
    '_part1_already_belongs_to_another_api_in_this_environme_bab95da8' => '«:part1» ya pertenece a otra API de este entorno. Una solicitud de token identifica un ámbito únicamente por su clave, así que cada clave solo puede pertenecer a una API.',
    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => ':part1 pertenecen a una API que esta aplicación no puede usar. Se excluyen de todos los tokens; elimínalos de los ámbitos introducidos.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 pueden iniciar sesión con contraseñas o con esta conexión. Exigir el inicio de sesión único rechaza todas las demás vías, de modo que ni siquiera los accesos ya emitidos puedan eludir al proveedor que acabas de configurar. La mayoría de las empresas que conectan un IdP quieren este comportamiento, pero primero lee sus efectos.',
    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 aún no tiene permisos, por lo que :part2 :part3 llega vacío. El nombre del rol sigue disponible para utilizarlo.:part4',
    '_part1_is_already_set_up_for_this_organization_change_i_dea89857' => ':part1 ya está configurado para esta organización. Cambia sus credenciales o elimina primero la conexión.',
    '_part1_is_no_longer_offered_anyone_who_signed_in_with_i_b1a43020' => ':part1 ya no se ofrece. Quienes lo usaron conservan su cuenta y pueden seguir usando su contraseña.',
    '_part1_is_off_on_every_sign_in_page_its_credentials_are_2dc58cfc' => ':part1 está desactivado en todas las páginas de inicio de sesión. Sus credenciales se conservan para que puedas volver a activarlo.',
    '_part1_is_off_on_this_organization_s_sign_in_page_its_c_5a7d1345' => ':part1 está desactivado en la página de inicio de sesión de esta organización. Sus credenciales se conservan para que puedas volver a activarlo.',
    '_part1_is_your_only_way_to_sign_in_set_a_password_or_ad_968a0fd3' => ':part1 es tu única forma de iniciar sesión. Establece una contraseña o añade una clave de acceso antes de desconectarlo.',
    '_part1_is_your_organization_s_single_sign_on_it_is_how_a02887f1' => ':part1 es el inicio de sesión único de tu organización. Es la forma en que tu organización te identifica, por lo que no puede desconectarse aquí.',
    '_part1_its_team_is_administered_under_organization_team_6abad4af' => ':part1 Su equipo se administra en Organización › Equipo, por alguien con un rol de la organización, no desde aquí.',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Todavía no hay nada definido por :part3 aquí. Cualquier cambio que hagas abajo se convierte en una regla propia de esta organización.',
    '_part1_part2_up_to_date_part3_deprovisioned_part4_part5_5604a19e' => ':part1 :part2 al día, :part3 desaprovisionados,:part4 :part5 omitidos, :part6 grupos :part7.',
    '_part1_part2_update_your_receiver_first_from_the_next_a_d1d60a6e' => ':part1 :part2 Actualiza primero tu receptor: a partir del siguiente intento, rechazará todas las entregas que no pueda verificar.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 rechaza el inicio de sesión si esto no coincide exactamente. El valor se conserva para esta configuración, así que puedes pegarlo ahora en :part2 y guardar aquí después.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1: las sesiones, claves de acceso y segundos factores, los perfiles de proveedores de identidad, los datos de directorio, los tokens emitidos, las asignaciones de roles y el historial de auditoría se conservan y pueden reactivarse.',
