    'you_can_also_part1_part2_part3_53f32513' => 'También puedes :part1 :part2 .:part3',
    'you_can_turn_it_off_again_on_part1_part2_sessions_that_89d71a9d' => 'Puedes volver a desactivarlo en :part1 :part2; las sesiones finalizadas seguirán finalizadas.',
    'you_hold_no_permissions_in_part1_so_a_key_would_identif_2c680207' => 'No tienes permisos en :part1, así que una clave solo te identificaría allí.',
    'your_endpoint_verifies_the_part1_header_on_each_request_b7ca1bb8' => 'Tu endpoint verifica la cabecera :part1 de cada solicitud con este secreto.',
    'your_roles_using_permission' => 'En :count de tus roles|En :count de tus roles',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Todo lo que tu organización ha configurado y lo que queda por hacer. La lista de configuración refleja el estado real: cada paso se marca automáticamente como completado cuando está hecho.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Toda la imagen de tu marca en una página: el logotipo, favicon, colores, tipografía y esquinas de la página de inicio de sesión alojada, con vista previa en directo, además del nombre del producto, el remitente de correo y el mensaje de bienvenida. Configúrala una vez para todo el entorno y todas las organizaciones la heredarán. También puedes personalizar una organización desde su pestaña Identidad visual.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'A partir del próximo intento, los bloqueos impedirán los inicios de sesión y los registros en este entorno, y los controles exigirán una verificación adicional. Una regla incorrecta puede dejar a personas reales sin acceso.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Otorga uno a las personas que soportan o ejecutan tus aplicaciones. El papel de una aplicación solo alcanza los tokens de esa aplicación; un papel para todas las aplicaciones llega a cada una de ellas.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'El número de organizaciones, usuarios, conexiones SSO, aplicaciones y sincronizaciones de usuarios de este entorno, con enlaces a sus respectivas páginas. Los accesos directos de abajo permiten crear los elementos más habituales: una organización, un usuario, una conexión SSO o una aplicación.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'El número de personas que han iniciado sesión y la frecuencia con la que tus aplicaciones han llamado a la API en los últimos 30 días. Esta vista te ayuda a evaluar la carga y detectar anomalías. No es una factura.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'La frecuencia con la que se obtienen los datos y los campos del sistema de RR. HH. que se copian para cada persona, como el centro de costes o la ubicación. Si cambias los campos, la siguiente sincronización será completa.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Cómo se exportan los registros de auditoría de Cbox ID: una exportación programada envía las entradas nuevas a tu SIEM o archivo cada cinco minutos. Una tarea diaria de conservación crea un punto de control del registro sin eliminar nada. Aquí puedes obtener el historial de auditoría de una persona para responder a una solicitud de acceso conforme al RGPD o comprobar, desde la consola de un entorno, que las exportaciones funcionan.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Si la aplicación declara otra URL más adelante, se retira esta aprobación y se te vuelve a solicitar. El destino al que se envían las contraseñas no debe cambiar sin tu aprobación. El inicio de sesión delegado facilita la transición: cuando queden pocas personas en el sistema antiguo, desactívalo y envíales un enlace para restablecer la contraseña.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'El botón desaparece y se eliminan sus credenciales. Quienes hayan usado esta conexión conservan su cuenta y pueden seguir usando su contraseña. Para conservar las credenciales, desactiva la conexión en lugar de eliminarla.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'También se eliminan sus ámbitos. Las aplicaciones que los tenían los conservan como ámbitos introducidos que ya no dan acceso a esta API. Los tokens ya emitidos siguen funcionando hasta que caducan.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Claves de la API de gestión de un entorno: administra sus organizaciones, miembros, invitaciones, roles y aplicaciones desde tu propio backend. Cada clave tiene ámbitos definidos explícitamente.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Claves que los usuarios de esta organización han creado para sus aplicaciones, con los permisos de cada una. Cada persona crea sus propias claves. Revoca las que se hayan filtrado o ya no se utilicen.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Déjalo vacío para casi todos los proveedores: sus tokens de ID se verifican con las claves de firma publicadas en su documento de descubrimiento (jwks_uri), incluidas las rotaciones. Pega la clave pública PEM del proveedor solo si no publica ninguna clave.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Permite iniciar sesión con una cuenta existente. Configura un proveedor una vez para el entorno y todas las organizaciones lo ofrecerán. Cada organización puede usar sus propias credenciales o desactivar un proveedor.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Permite que los usuarios de tus aplicaciones conecten sus propias cuentas de GitHub, Google, Slack o Salesforce para que las aplicaciones llamen a esas API en su nombre. Sus tokens se almacenan cifrados, se renuevan aquí y se facilitan temporalmente solo a las aplicaciones que autorices.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Permite a tus usuarios iniciar sesión con su cuenta de empresa existente de Microsoft Entra ID, Okta o Google Workspace, en lugar de usar una contraseña independiente aquí. Conecta tu proveedor de identidad y verifica tus dominios de correo una sola vez. Después, todas las personas de esos dominios se dirigirán a tu proveedor para iniciar sesión.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'El inicio de sesión con Entra ID, Okta o Google Workspace está disponible en el plan Enterprise. Contacta con tu equipo de atención al cliente para activarlo en esta organización.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Enlaces entregados al administrador de TI de esta organización que siguen siendo válidos. Si revocas uno, deja de funcionar inmediatamente. La configuración ya realizada mediante ese enlace se conserva.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Busca una organización por nombre o identificador corto, o un usuario por nombre o correo, en todos los entornos de esta instalación, no solo en el que muestra la consola. Utilízalo cuando alguien pida ayuda y no sepas en qué entorno se encuentra.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Los esquemas de metadatos usan un subconjunto de JSON Schema: un objeto cuyas propiedades son cadenas, números, enteros, booleanos o null, con reglas para valores permitidos, longitud, rango, patrón y formato. Guardar un cambio crea una versión nueva. Los eventos ya registrados conservan la versión con la que se validaron.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Envía cada entrada nueva del registro de auditoría a las herramientas de tu equipo de seguridad, como un SIEM, en cuanto se registra. Configúralo para que las investigaciones comiencen en las herramientas que el equipo ya utiliza, sin solicitar primero una exportación. La entrega se realiza al menos una vez, por lo que puede haber duplicados ocasionales.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Para la mayoría de las integraciones son más adecuados los webhooks: se ejecutan después del evento y no pueden bloquear el proceso. Usa un hook solo cuando tu sistema deba intervenir mientras se inicia sesión o se emite un token.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'No se emite ningún secreto nuevo. A partir del próximo intento, incluidos los reintentos, las entregas llevarán las cabeceras del otro método. Un receptor que no se haya actualizado las rechazará todas.',
    'nobody_is_on_this_organization_it_has_no_owner_so_nobod_0a51d66d' => 'Esta organización no tiene miembros ni propietario, por lo que nadie puede iniciar sesión para administrarlo. Se trata de un fallo de aprovisionamiento que debe investigarse, no solo de una lista vacía.',
    'nothing_is_always_refused_and_nothing_skips_the_rules_d_6699d9d9' => 'No hay entradas que se rechacen siempre o queden exentas de las reglas. Bloquea un rango de direcciones desde el que hayas recibido ataques o exime a la red de tu oficina de las reglas de frecuencia de inicio de sesión.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Muestra Google, GitHub, Apple y otros proveedores como botones en tu página de inicio de sesión para quienes prefieren una cuenta existente a otra contraseña. Configura un proveedor una vez para el entorno y todas las organizaciones lo ofrecerán. Una organización puede usar sus propias credenciales o desactivar un proveedor. Tú aportas las credenciales y el resto se rellena automáticamente. Una dirección de correo enviada por un proveedor nunca basta por sí sola para acceder a una cuenta existente aquí.',
    'on_for_this_percentage_of_everyone_the_rules_above_do_n_6ca1e886' => 'Se activa para este porcentaje de personas a las que no se aplican las reglas anteriores. Un hash estable del ID de usuario selecciona siempre a las mismas personas; aumentar el porcentaje solo añade más. Déjalo vacío si no quieres un despliegue gradual.',
    'one_marked_event_siem_stream_test_sent_now_with_this_st_c0cf0c4a' => 'Se envía ahora un evento marcado (siem.stream.test) con la configuración y las credenciales de este flujo, sin cola ni reintentos. Si se envía correctamente, también se elimina la indicación «Acción requerida».',
    'one_per_line_including_the_scheme_https_app_example_com_71de2531' => 'Una entrada por línea, incluido el protocolo, por ejemplo https://app.example.com. Si una línea no es válida, se rechaza toda la lista. Las líneas incorrectas no se descartan en silencio.',
    'one_type_per_resource_type_its_relation_s_below_it_a_re_18943de8' => 'Un `type` por tipo de recurso, con sus entradas `relation` debajo. Una relación se determina mediante los sujetos que una tupla nombra directamente ([user, group#member]), otra relación (owner), una relación de un recurso superior (viewer from parent) o una combinación con or, and o but not.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Una organización de esta instalación, con su equipo, sus proyectos y todos los entornos de esos proyectos. Al suspenderlo, se cierran las sesiones de sus miembros y se detiene la autenticación en todos esos entornos.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Solo para proveedores que no publican sus claves de firma (jwks_uri) en el documento de descubrimiento. En caso contrario, se obtienen de ahí, incluso después de una rotación. Introduce una clave pública PEM. Se almacena cifrada y no se vuelve a mostrar. Déjalo vacío para conservar la clave actual.',
    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Solo los miembros activos de la organización que elijas pueden iniciar sesión en esta aplicación. Se deniega el acceso a los demás y la denegación se registra en el registro de auditoría.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Los detalles de la organización en el entorno de destino: miembros, SSO, dominios, derechos asignados y actividad reciente. En esta página solo puede cambiarse el estado de la organización.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Las organizaciones, usuarios y sesiones activas de todos los entornos de esta instalación, además de las organizaciones con más miembros. Esta vista solo lee datos y nunca cambia el entorno seleccionado en la consola.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Elige el framework que usas y se creará una aplicación con una redirección a tu servidor de desarrollo local, las variables de entorno para copiar y el código de inicio de sesión. La página espera hasta que alguien inicie sesión de verdad. Debajo están los pasos para convertirla en un producto: identidad visual, organizaciones, SSO, un agente, un compañero y producción. Cada paso se marca automáticamente según el estado real del entorno, nunca a mano.',
    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Los operadores de plataforma administran todos las organizaciones y entornos de esta instalación desde un nivel superior. Añade como operador solo a quien sea responsable de la propia instalación y suspende su acceso cuando deje de ser su función.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Conecta un proveedor de identidad a nuestro endpoint SCIM, conecta Google Workspace o Microsoft Entra, o vincula tu sistema de RR. HH.: Workday, BambooHR, Rippling, HiBob o Personio. Obtendremos los datos de las personas de los sistemas conectados de forma programada.',
    'prove_which_email_domains_your_organization_owns_a_veri_a1717fad' => 'Verifica qué dominios de correo pertenecen a tu organización. Un dominio verificado puede enviar a todas las personas con una dirección de ese dominio directamente a tu conexión SSO empresarial.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar evalúa cada inicio de sesión y registro: intentos con credenciales robadas, velocidad propia de bots, desplazamientos geográficamente imposibles, dispositivos nuevos, redes de anonimización y direcciones desechables, además de tus reglas y listas de permitidos y bloqueados. Registra cada decisión. Al activar la aplicación de las reglas, Radar bloquea el acceso o solicita un segundo factor. Revisa las decisiones aquí antes de activarla y cuando alguien indique que no puede iniciar sesión.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar evalúa cada inicio de sesión y registro: intentos con credenciales robadas, velocidad propia de bots, desplazamientos geográficamente imposibles, dispositivos nuevos, redes de anonimización y direcciones desechables, además de tus reglas y listas. Registra los motivos de cada decisión.',
    'refuse_passwords_found_in_known_data_breaches_checked_a_db4c6959' => 'Rechazar contraseñas que aparezcan en filtraciones de datos conocidas. Se comprueban con Have I Been Pwned sin enviar nunca la contraseña. Si no se puede acceder al servicio, se permite el registro en lugar de bloquearlo.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Registra aplicaciones que aceptan este entorno como proveedor de identidad SAML. Sus usuarios inician sesión con las cuentas que ya tienen aquí. Asocia cada aplicación a su organización para que solo puedan acceder sus miembros. Sin esa asociación, estará abierta a todas las personas del entorno. Esta es la dirección saliente. Para permitir el acceso con una cuenta de empresa externa, usa SSO empresarial en Autenticación.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Las solicitudes aparecen aquí automáticamente cuando una aplicación o agente necesita tu aprobación para actuar en tu nombre. No tienes que hacer nada hasta entonces. Deniega cualquier solicitud que no hayas iniciado.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Las solicitudes de agentes que quieren actuar en nombre de un usuario aparecen aquí al llegar. Cada usuario aprueba sus propias solicitudes. Esta página permite denegar las que parezcan abusivas.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Ahora las personas inician sesión con credenciales almacenadas aquí. Conecta tu proveedor para que utilicen la cuenta de empresa que ya tienen. Perderán el acceso aquí en cuanto desactives su cuenta en el proveedor.',
    'scopes_sign_out_uris_token_settings_and_the_roles_manif_c736e69a' => 'Los ámbitos, las URI de cierre de sesión, la configuración de tokens y la URL del manifiesto de roles se copian sin cambios. Los secretos, las claves y los usuarios de la aplicación no se copian: pertenecen al entorno en el que se crearon.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Ve la aplicación exactamente como uno de sus usuarios: inicias sesión en su nombre por el motivo que indiques y durante una hora como máximo. La aplicación recibe tu identidad real y no obtiene ningún mecanismo para prolongar la sesión. El registro de auditoría de la organización deja constancia de quién lo hizo y por qué.',
    'send_this_single_use_link_to_whoever_configures_your_id_e8056999' => 'Envía este enlace de un solo uso a quien configure tu proveedor de identidad. Caduca pronto y funciona sin cuenta. Cópialo ahora: solo se muestra una vez.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Envía este enlace de un solo uso a quien gestione el proveedor de identidad de la organización, si no lo ha recibido ya por correo. Funciona sin cuenta hasta que caduca. Cópialo ahora: solo se muestra una vez.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Ofrece los endpoints de identidad de un entorno en un dominio que te pertenece, como login.example.com, en lugar del nuestro. Demuestras la propiedad mediante un registro DNS TXT. Configúralo si las personas deben ver únicamente tu propia dirección al iniciar sesión.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Establece esto como política de confianza del rol (IAM › Roles › Trust relationships). La plataforma solo podrá asumir el rol si presenta el ID externo de este flujo. Así, nadie más en la plataforma podrá dirigir un flujo hacia tu rol.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Los inicios de sesión y las solicitudes que Cbox ID ha considerado suficientemente arriesgados para señalarlos, del más reciente al más antiguo, con su puntuación y motivos. Revisa esta vista tras un aumento de los intentos fallidos o cuando alguien informe de un inicio de sesión que no realizó.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Inicios de sesión, tokens emitidos, usuarios nuevos y activaciones de la autenticación de dos factores, día a día durante los últimos 30 días, salvo que se configure otro periodo. La página permanece vacía hasta que quien administra la instalación configure el almacenamiento de los datos de análisis.',
    'snapshots_every_admin_support_role_each_role_held_acros_351f6f6d' => 'Captura todos los roles de administración y soporte de todo el entorno como elementos que deben certificarse o revocarse. Al revocar uno, se retira el rol de todas las organizaciones a la vez.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Software que actúa en este entorno con una clave de gestión: Claude Code, Cursor, un bot interno o tu propio backend. Cada uno tiene solo los ámbitos que le has asignado y espera tu aprobación para las acciones que hayas elegido.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Algunos roles nunca deben asignarse a la misma persona: quien crea un pago no debería aprobarlo también. Define esas parejas aquí. Cbox ID bloquea las nuevas asignaciones que infrinjan la regla y muestra quién ya tiene ambos roles.',
    'splunk_elastic_graylog_cef_and_generic_json_are_http_co_8d405816' => 'Splunk, Elastic, Graylog, CEF y Generic JSON son receptores HTTP para los que debes indicar una URL. Datadog, Amazon S3 y Google Cloud Storage usan su propia configuración.',
    'start_from_the_documents_in_folders_example_owners_edit_ca2a0af5' => 'Empieza con el ejemplo de documentos en carpetas: propietarios, editores y lectores, con los permisos de cada carpeta heredados por todo su contenido. Las tuplas y las comprobaciones de permisos necesitan primero un esquema.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Opciones de funcionalidad que tus aplicaciones consultan para una persona en una organización. Activa una función para usuarios u organizaciones concretos, o para un porcentaje de todos los usuarios. Cada aplicación recibe la misma respuesta, en el token o mediante la API.',
    'the_address_tokens_for_this_api_name_as_their_audience_cdea85aa' => 'La dirección que los tokens de esta API indican como audiencia y que tu API comprueba. No puede cambiarse después, porque todos los tokens ya emitidos contienen ese valor.',
    'the_agent_is_refused_and_cannot_act_on_this_person_s_be_e1cd49d2' => 'Se deniega la solicitud del agente y no puede actuar en nombre de esta persona. La denegación queda en el registro de auditoría y no puede deshacerse. El agente tendría que solicitarlo de nuevo.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Los eventos de auditoría que tu aplicación envía para cada organización a la que presta servicio: quién hizo qué en tu producto y cuándo. Se guardan por organización en una cadena de hashes y se muestran a sus administradores. Úsalo cuando una organización solicite el registro de auditoría de su cuenta. Define esquemas para mantener la coherencia de los eventos.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Los eventos de auditoría que tu aplicación envía para todas las organizaciones a las que presta servicio, del más reciente al más antiguo. Los eventos de cada organización forman su propia cadena de hashes.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'El registro de auditoría está aquí y las herramientas de tu equipo de seguridad están en otro lugar. Un flujo les envía cada entrada nueva en cuanto se registra, para que una investigación no tenga que empezar solicitando una exportación CSV.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'El botón desaparece de la página de inicio de sesión de esta organización. El proveedor del entorno no lo sustituye. Las credenciales se conservan para que puedas volver a activar la conexión.',
    'the_ceiling_on_this_app_s_access_narrowing_it_takes_eff_5f2865bc' => 'El límite máximo de acceso de esta aplicación. Reducirlo tiene efecto a partir del siguiente token. Si un dispositivo o agente solicita un ámbito que eliminas, se rechaza la solicitud en lugar de conceder menos permisos sin avisar.',
    'the_destination_refused_the_settings_a_missing_bucket_a_27207d67' => 'El destino ha rechazado la configuración, por ejemplo porque falta un bucket o la región o el sitio son incorrectos. No se entrega nada hasta que se corrija. Las entradas quedan en espera y no se descartan.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Los dominios de correo de esta organización, cada uno verificado con un registro DNS TXT. Una vez verificado un dominio, puedes imponer la redirección de todas las personas con una dirección de ese dominio a tu conexión SSO empresarial, en lugar de usar una contraseña. Verifica todos los dominios que utilizan tus usuarios antes de depender del SSO.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Las claves que tu código usa para llamar a Cbox ID, con una pestaña por tipo. Una clave secreta de gestión permite a tu backend administrar las organizaciones, miembros, invitaciones, roles y aplicaciones de un entorno. Una clave de organización llama a su API con un rol integrado. Una clave publicable se usa en una aplicación de navegador y solo funciona desde los orígenes permitidos. Las claves secretas y de organización solo se muestran una vez. Cópialas al crearlas y revócalas inmediatamente si se filtran.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'La dirección inversa: Cbox ID envía a tus usuarios a los demás productos SaaS de tu empresa mediante sus endpoints SCIM. Gestionas las altas y bajas en un solo lugar, en vez de usar un panel de administración por proveedor.',
    'the_name_of_your_organization_which_your_projects_envir_fde906b5' => 'El nombre de tu organización, que agrupa tus proyectos, entornos y equipo y se muestra en toda la consola. Eliminar una organización desactiva todos sus entornos de inicio de sesión. Por eso se solicita a soporte, en lugar de hacerlo con un botón.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Las reglas de contraseña, el bloqueo de cuenta y los requisitos de autenticación de dos factores y SSO que se aplican en cada inicio de sesión. Para todo el entorno también se configura si se ofrecen claves de acceso y enlaces de inicio de sesión, y cuánto duran las sesiones. El entorno define una base que heredan todas las organizaciones. Estas pueden endurecer las reglas de contraseña y de dos factores, pero nunca suavizarlas.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Tus servicios que reciben tokens de acceso y los ámbitos de cada uno. Tú decides a quién conceder los ámbitos de una API registrada. Nadie puede limitarse a escribirlos en una aplicación para obtener acceso a tu API.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Todo el entorno ofrece este proveedor en cada página de inicio de sesión. Elige una organización para configurar un proveedor propio. Este sustituirá al del entorno en la página de inicio de sesión de esa organización.',
    'the_organization_s_own_keys_for_the_organization_api_li_86017b30' => 'Las claves propias de la organización para su API: listar proyectos y entornos, crear entornos y listar e invitar a miembros del equipo. Cada clave tiene un rol integrado.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Se revocan las sesiones y los tokens de la persona. Se eliminan sus claves de acceso, segundos factores, membresías, asignaciones de roles, tokens API, secretos de la bóveda, dispositivos y todas las copias almacenadas de sus datos. La cuenta se conserva únicamente como un registro seudonimizado y desactivado. Las aplicaciones que sincronizan personas desde aquí reciben una solicitud de eliminación. El registro de auditoría conserva el ID opaco, no el nombre ni la dirección de correo.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Estos hooks se ejecutan durante una operación, no después, y su respuesta cambia el resultado. Tu endpoint puede añadir información a un token o rechazar por completo un inicio de sesión. Intervienen directamente en el proceso, por lo que un endpoint lento o defectuoso afecta a la persona que intenta acceder.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'La persona pierde inmediatamente el acceso a todas las páginas de plataforma de esta instalación. Sus sesiones existentes dejan de funcionar en la siguiente solicitud. Puedes reactivarla aquí.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Esta acción no se puede deshacer. Se eliminan sus credenciales, membresías y datos personales, y la cuenta se seudonimiza. Si es la única persona propietaria de una organización, transfiere primero la propiedad.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Esta instalación no tiene claves de Turnstile (CBOX_ID_TURNSTILE_SITE_KEY), por lo que no puede activarse esa comprobación. En los registros señalados se verifica la dirección de correo en su lugar.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Este endpoint pertenece al entorno y se ejecuta para todas sus organizaciones. Se muestra aquí porque interviene en tus inicios de sesión. Lo administra tu operador.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Este entorno ofrece un servidor MCP junto a su API REST. Conecta un agente con una clave de gestión y podrá realizar exactamente lo que permitan sus ámbitos, con las mismas comprobaciones, aprobaciones y registro de auditoría que la consola.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Este entorno ofrece un servidor MCP, la interfaz estándar para que los asistentes de IA llamen a herramientas, junto a su API REST. Introduce la dirección y una clave de gestión en Claude Code, Cursor o cualquier otro cliente MCP. El agente podrá realizar exactamente lo que permitan los ámbitos de la clave, con las mismas comprobaciones y registro de auditoría que la consola.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Este usuario ya no puede iniciar sesión en ninguna aplicación del entorno. Sus sesiones existentes dejan de funcionar en la siguiente solicitud. Sus datos se conservan y puedes reactivarlo en cualquier momento.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Este usuario posee o administra una organización. No se puede actuar con la identidad de estas cuentas, porque eso podría conceder a otra persona un control duradero sobre la organización.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Actualmente se añaden y eliminan personas aquí de forma manual. Conecta el directorio que ya utiliza tu empresa para automatizar ambas operaciones, incluidas las bajas que suelen olvidarse.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Hasta que se registra una API, un ámbito es solo texto en una aplicación. Cualquier persona que pueda editarla puede asignarle cualquier ámbito. Registra las API que llaman tus aplicaciones para que sus ámbitos tengan un propietario.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Los dominios verificados dirigen a las personas a tu propio proveedor de identidad. Esta función forma parte del plan Enterprise. Contacta con tu equipo de atención al cliente para activarla en esta organización.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Verificar un dominio que te pertenece, como acme.com, permite a Cbox ID reconocer a tus usuarios por su correo y enviarlos directamente a tu proveedor. Así nadie tiene que elegir el botón correcto para iniciar sesión.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Los webhooks, avisos de cierre de sesión a aplicaciones conectadas, actualizaciones de roles obtenidas de esas aplicaciones y correos en cola se procesan en segundo plano mediante workers de cola, sin hacer esperar a la persona. Si no hay ningún worker activo, nada de esto se procesa, aunque el resto de la consola parezca normal. Esta página permite detectar el problema.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Las acciones de los agentes de este entorno que esperan aprobación. Si la clave la requiere, el agente se detiene y pregunta a quien la creó. Esa persona puede responder en el teléfono o aquí. Quienes administran el entorno pueden denegar solicitudes sospechosas. Debajo aparecen solicitudes de aplicaciones que quieren actuar en nombre de un usuario; cada usuario aprueba las suyas.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Lo que se puede permitir hacer a una aplicación en esta API. Tus propias aplicaciones pueden tener cualquiera de estos ámbitos. Las registradas por una organización solo pueden tener los marcados para organizaciones.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Las acciones del software de este entorno que esperan aprobación. Un agente cuya clave la requiere se detiene y pregunta a quien creó la clave. Responde aquí o desde el teléfono.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'La clave que solicita tu código y que contiene el claim feature_flags. Letras minúsculas y dígitos, con - _ o . entre ellos. No puede cambiarse después.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Cuando una aplicación o un agente de IA necesita tu aprobación para actuar en tu nombre, no siempre puede pedirla en la pantalla que estás usando. Por eso la solicita aquí. Aprueba solo las solicitudes que hayas iniciado y comprueba que el código coincide con el del dispositivo que la ha solicitado.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Cuando se cumplen TODAS las condiciones, Radar ejecuta la acción de esta regla y no evalúa las posteriores. Estas reglas se evalúan después de las listas de permitidos y bloqueados y antes de las reglas integradas.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'El destino al que Cbox ID envía a las personas después de cerrar sesión en esta aplicación. La URI solicitada debe aparecer aquí exactamente, incluida cualquier barra final. Si no coincide, la persona permanece en la página de sesión cerrada de Cbox ID. Déjalo vacío si la aplicación nunca solicita una redirección de vuelta.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Dónde has iniciado sesión, qué puede actuar en tu nombre y qué ha ocurrido en tu cuenta. Si ves una sesión que no reconoces, ciérrala y cambia tu contraseña.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Durante la migración desde otro sistema, tu aplicación puede indicar su antiguo endpoint de inicio de sesión en el manifiesto, junto a sus roles. Aparece aquí para que lo apruebes antes de utilizarlo.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Durante la migración desde otro sistema, una aplicación puede solicitar que el correo y la contraseña de quienes aún no existen en Cbox ID se comprueben en su antiguo endpoint de inicio de sesión. Pruébalo antes de aprobarlo. Las personas que acepte se crean aquí y no vuelven a enviarse allí. Sin embargo, si el endpoint no funciona, quienes aún no hayan migrado no podrán iniciar sesión.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Sin roles, todas las personas que pueden iniciar sesión reciben los permisos que la aplicación da a un usuario normal. Con los roles defines una vez quién puede editar y quién pertenece a soporte, por ejemplo, y todas las aplicaciones conectadas pueden respetar esa distribución.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Crea una regla para permitir, solicitar verificación adicional o bloquear según lo que sabes de tus usuarios. Por ejemplo, exige verificación adicional en accesos desde países donde no operas o exime a la red de tu oficina de las reglas de frecuencia de inicio de sesión.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Actúas como esta persona, en su sesión y con sus permisos. El acceso está limitado a 30 minutos y es de solo lectura donde la consola puede imponerlo. Cada solicitud queda registrada a tu nombre.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Pierdes el acceso inmediatamente. Como propietario, solo puedes salir de la organización cuando otra persona sea su propietaria. Transfiere primero la propiedad o elimina la organización en Configuración.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'El modelo de acceso de tu aplicación: tipos de recursos como documentos y carpetas, relaciones como propietario, editor y lector, y cómo se heredan. Quienes pueden leer una carpeta pueden leer todos sus documentos. Tu aplicación guarda las relaciones entre personas y recursos y pregunta en cada solicitud: «¿puede este usuario editar este documento?». El esquema determina la respuesta.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'El modelo de acceso de tu aplicación: tipos de recursos, relaciones de cada tipo y cómo se heredan. La aplicación escribe tuplas — quién se relaciona con qué — y comprueba los permisos en cada solicitud.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Tu aplicación envía estos eventos con una llamada por lote. Cada evento indica la organización en la que ocurrió. Aparecen aquí y para los administradores de esa organización a medida que llegan.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'La identidad visual predeterminada del entorno: aspecto, logotipo y favicon del inicio de sesión alojado, así como el nombre y el remitente que ven los usuarios. Cada organización la hereda, salvo que defina la suya.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Tu proveedor de identidad crea, actualiza y desactiva personas aquí automáticamente mediante el estándar SCIM. Las altas y bajas del sistema de RR. HH. llegan a tus aplicaciones en segundos, sin solicitudes de soporte ni cuentas olvidadas — algo esencial cuando alguien se marcha.',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Tus propios métodos de inicio de sesión y sesiones activas. Una clave de acceso ofrece la mayor protección y es la más rápida de usar: tu dispositivo la desbloquea con la huella o el rostro, y no queda ninguna contraseña que puedan robar mediante phishing.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Tu receptor conserva el mismo secreto. Un secreto hexadecimal de 64 caracteres se convierte en whsec_ seguido de la codificación base64 de esa cadena — "whsec_" + base64(secret). Si el secreto ya empieza por whsec_, se usa sin cambios.',
    '_groups_part1_39d243e0' => '{
  "groups": [":part1"]
}',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => ':part1 tareas recomendadas, aproximadamente en este orden. Cada una se marca automáticamente como completada cuando realmente está hecha. No tienes que marcar nada manualmente.',
    '_sub_the_person_s_id_org_the_organization_they_are_acti_2e2ddc7f' => '{
  "sub": "el ID de la persona",
  "org": "la organización en cuyo nombre actúa",
  "roles": [":part1"],
  "permissions": [:part2]
}',
    'an_api_key_organization_settings_api_keys_not_an_applic_916c023d' => 'Una clave API (Configuración de la organización › Claves API), no una clave de aplicación. Se almacena cifrada y no se vuelve a mostrar.:part1',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Cómo la gente inicia sesión en :part1. Estos comienzan como los valores predeterminados de tu entorno; cualquier cosa que cambies aquí solo puede hacerlos más estrictos.',
    'its_members_are_signed_out_and_all_part1_it_owns_stop_s_80b419eb' => 'Sus miembros están firmados y todos los :part1 que posee dejan de servir auth en la siguiente solicitud. Puede reactivarlo aquí.',
    'its_part1_are_signed_out_and_all_part2_it_owns_stop_ser_c1a0c179' => 'Sus :part1 están firmados y todos los :part2 que posee dejan de servir auth en la siguiente solicitud. Puede reactivarlo aquí.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Sus :part1 ya no pueden iniciar sesión en esta organización, y las aplicaciones que dependen de ella dejan de autenticarlos. Las suborganizaciones no se suspenden junto con ella. Puedes reactivarla aquí.',
    'minutes_at_most_part1_empty_uses_the_deployment_s_part2_2c261db9' => 'Minutos, como máximo :part1. Vacío utiliza la implementación :part2. Acortando también termina sesiones más largas ya en ejecución.',
    'only_if_your_app_needs_more_from_part1_than_sign_in_doe_fc539001' => 'Solo si tu aplicación necesita más de :part1 que el inicio de sesión, separado por espacios. Siempre se solicitan los propios visores de inicio de sesión.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Pegue todo el archivo de claves JSON de una cuenta de servicio con roles/almacenamiento concedidos.objetoCreator en el cubo. Almacenado encriptado y nunca mostrado de nuevo.:part1',
    'sandbox_environments_allow_localhost_urls_and_never_sen_299fef2d' => 'Los entornos Sandbox permiten URLs de host local y nunca envían email real. :part1 restantes en el plan de este proyecto.',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Inicie sesión en una de sus aplicaciones como :part1 para ver lo que ven. La aplicación se le dice que es usted, y el registro de auditoría de la organización registra quién, cuándo y por qué.',
    'the_app_whose_declared_roles_and_permissions_tokens_for_f9092feb' => 'La aplicación cuyos roles declarados y permisos tokens para esta API llevar. Sólo las aplicaciones de propiedad de :part1 se pueden elegir.',
    'what_part1_s_sign_in_page_offers_providers_from_the_env_efc01f8e' => 'Lo que ofrece la página de inicio de sesión de :part1. Los proveedores del medio ambiente son heredados; esta organización puede desactivar uno, o establecer el suyo propio en su lugar.',
    'when_an_agent_s_key_needs_approval_for_an_action_the_re_56c5e366' => 'Cuando la clave de un agente necesita aprobación para una acción, la solicitud aparece aquí y en el teléfono de la persona que creó la llave. Espera hasta :part1.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => '¿Qué formas en :part1 ofrece además de una contraseña, y cuánto tiempo dura un inicio de sesión. Estos son los mismos para cada organización en ella.',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 El claim :part2 tiene otro significado: indica lo que la :part3 :part4 podía solicitar, no lo que esta :part5 puede hacer.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 No sirven para iniciar sesión en esta consola: los administradores acceden mediante Cbox ID en :part2, con sus métodos de inicio de sesión.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Marca el ámbito :part2 :part3 al registrar la aplicación. El token de ID incluirá los mismos nombres de roles en un claim :part4, el nombre que buscan Kubernetes, Grafana y Vault. No hace falta crear nada más.',
    '_part1_you_are_impersonating_part2_part3_for_support_ev_aaad4d39' => ':part1 Estás suplantando la identidad de :part2 :part3 para prestar asistencia. Todo lo que hagas quedará registrado. :part4 :part5 :part6',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Una clave de gestión solo actúa en su propio entorno. Exporta el blueprint de esta app (GET /apps/{id}/blueprint) y regístralo con la clave del otro entorno (POST /apps con `blueprint`).',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Una clave de gestión para un solo agente. Solo puede hacer lo que permiten sus ámbitos, y las acciones que elijas esperarán tu aprobación, en el teléfono o en :part1.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'Una página en :part1. Déjalo vacío para llegar a la consola, con :part2 indicado en la invitación.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => 'Un :part1 es el IdP de un producto. Contiene :part2 :part3 aislados, producción y sandbox, cada uno con sus propios usuarios, claves e inicio de sesión, y se factura según su propio plan.',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'Un permiso determina lo que una :part1 puede hacer tras iniciar sesión. Lo que una :part2 puede solicitar es un ámbito, que se configura al registrarla en :part3 :part4.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'Una clave de la organización da acceso al propia organización, con sus proyectos, entornos, equipo y claves, pero no al interior de un entorno. Crea una en :part1 :part2 :part3, en la raíz de la plataforma.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Los tokens de acceso de esta app indican :part1 como su audiencia :part2. Esa API solo debe aceptar un token si la identifica como destinataria.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Los tokens de acceso de esta aplicación indican como audiencia el emisor de este entorno, :part1 :part2. Esto cambia cuando la aplicación tiene un ámbito de una de tus API registradas.',
    'add_a_txt_record_at_part1_part2_with_the_value_below_th_455edc17' => 'Añade un registro TXT en :part1 :part2 con el valor indicado abajo y haz clic en Verificar. Los cambios de DNS pueden tardar unos minutos en propagarse.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'Una app registra su catálogo mediante el SDK.:part1 :part2 Puedes crear el rol ahora y definir su contenido cuando lleguen las claves.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Aplicaciones que confían en este entorno como proveedor de identidad SAML. Para permitir que las personas accedan con una cuenta que ya tienen en otro lugar, utiliza :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Las aprobaciones cubren las acciones de la API de gestión. Estos ámbitos se ofrecen mediante endpoints que todavía no son acciones, por lo que se ejecutan sin solicitar aprobación: :part1 :part2.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Las apps envían a las personas al registro con :part1 y piden a quienes ya han iniciado sesión que creen una organización con :part2. Ambas opciones solo se ofrecen mientras esta configuración está activada.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'La comprobación se solicita exactamente como la solicita tu app (:part1), teniendo en cuenta todas las herencias definidas por el esquema.',
    'auth_settings_differ' => ':count ajuste difiere de tu entorno.|:count ajustes difieren de tu entorno.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Conecta una sola vez en la raíz de la plataforma, en lugar de hacerlo por separado en cada entorno. Con tu identidad, la conexión accede a tu organización, a todos sus entornos que administras y a tu propia cuenta. Una herramienta de entorno utiliza un argumento :part1 :part2, y la API REST una cabecera :part3, para indicar dónde actuar. Puede hacer lo que tú puedes hacer, dentro de lo que autorices, y cada acción crítica espera tu aprobación en tu dispositivo.',
    'each_new_account_creates_its_own_organization_and_owns_3528fda3' => 'Cada cuenta nueva crea su propia organización y se convierte en su propietaria. Las apps también pueden pedir a una persona que ya ha iniciado sesión que cree una con :part1 :part2.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Cada organización le asigna un :part1, que determina lo que puede administrar en ella, y cualquier número de :part2, que determinan lo que puede hacer en sus apps.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Entorno «:part1» creado. Añade :part2 desde la configuración de dominios del entorno para verificarlo mediante DNS. Un dominio sin verificar no puede ser su emisor.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'Los entornos pertenecen a un proyecto y cada proyecto a un :part1 :part2 :part3. Empieza ahí para ver todos los recursos de una organización. Hay dos tipos de filas que nunca tienen una organización: :part4 es el entorno en el que se ejecuta esta instalación, donde residen los operadores y las personas de las organizaciones; un entorno :part5 :part6 no tiene proyecto, por lo que no se factura ni es accesible desde ninguna organización. Ninguno de los dos casos es un error que deba corregirse en esta pantalla, que tampoco permite reasignarlos.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Todos los métodos con los que las personas acceden a :part1, si están activados y dónde se modifican. Las organizaciones pueden aplicar reglas más estrictas:part2 :part3.',
    'every_organization_environment_and_operator_on_part1_a__f425b7e6' => 'Todos las organizaciones, entornos y operadores de :part1. Una suspensión, un entorno nuevo o un cambio de operador realizado aquí se aplica a todos ellos.',
    'feature_flag_part1_created_it_is_off_for_everyone_until_32603be3' => 'Feature flag «:part1» creado. Está desactivado para todos hasta que una regla de abajo o su valor predeterminado lo active.',
    'framework_3cf574caed49' => 'Los ámbitos :value1 pertenecen a una API registrada cuyos ámbitos este cliente no puede tener. Un cliente propiedad de una organización puede tener ámbitos de las API de su propia organización y aquellos de las API del entorno que las organizaciones tengan permitido solicitar.',
    'framework_43fd205dea6a' => 'El ámbito [:key] ya pertenece a otra API de este entorno. Las claves de los ámbitos son únicas por entorno, porque una solicitud de token identifica un ámbito únicamente por su clave.',
    'framework_47867973811e' => 'La sincronización del directorio con :provider ha fallado: :request alcanzó el límite de solicitudes (HTTP :status). Número de intentos: :attempt.',
    'framework_5eb368b0fb37' => 'Workday: la URL del informe debe ser la dirección de su servicio web: …/ccx/service/customreport2/{tenant}/{owner}/{report}.',
    'framework_632573ec7b49' => 'La app [:clientId] debe tener el mismo propietario que la API cuyas reglas de acceso aplica. Vincularla incluiría los roles y permisos de un propietario en los tokens de otro.',
    'framework_87da9891b0ad' => 'La sincronización del directorio con :provider ha fallado: :request no estaba disponible (HTTP :status) después de :attempt intentos.',
    'framework_98eb4683e38b' => 'La sincronización del directorio con :provider ha fallado: :request ha fallado (HTTP :status): recurso no encontrado. Revisa la cuenta, el subdominio o la dirección del informe.',
    'framework_a934fd6a0c26' => '[:origin] utiliza http, por lo que la clave y todo lo que la página haga con ella viajarían sin cifrar por la red. Utiliza https o, durante el desarrollo, un host de loopback como http://localhost:3000.',
    'framework_b63785ee57fb' => 'La sincronización del directorio con :provider ha fallado: :request ha fallado (HTTP :status): las credenciales no tienen permiso para leer los datos de los empleados.',
    'framework_e5ca82ab9dff' => 'La sincronización del directorio con :provider ha fallado: :request ha fallado (HTTP :status): las credenciales han sido rechazadas.',
    'framework_fc1964a8e8c4' => 'Ese es el último secreto activo del cliente [:clientId]. Rota el secreto para sustituirlo; si lo revocas, el cliente no podrá autenticarse.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Si ese endpoint es :part1, las personas que aún no han migrado no pueden iniciar sesión. Quienes ya se han migrado no se ven afectados.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'En el orden en que los ven las personas. Desactivar aquí uno de los métodos del entorno solo elimina el botón de esta página; no impide que se utilice para acceder desde otro lugar. Para que tu proveedor de identidad sea la única vía de acceso, exige SSO en :part1 :part2.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Las claves empiezan por este prefijo, de modo que una clave encontrada en un registro permite identificar esta aplicación: :part1 :part2. De 2 a 16 letras minúsculas o dígitos, seguidos de :part3 o :part4 :part5, únicos en este entorno. Definir un prefijo activa las claves. Borrarlo impide crear claves nuevas; las ya creadas siguen funcionando hasta que se revoquen.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Listar los indicadores de funcionalidad con sus reglas de segmentación y evaluar cada indicador para un usuario de una organización. Es lo que solicita el backend de una aplicación cuando no dispone de un token.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Listar los directorios (SCIM, Google Workspace, Microsoft Entra) que sincronizan personas, sus grupos y los errores de sincronización, sin mostrar nunca tokens bearer ni credenciales de proveedores.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Listar las conexiones SAML y OIDC que usan las organizaciones para iniciar sesión y los dominios de correo que dirigen a las personas hacia ellas, sin mostrar nunca certificados, secretos de cliente ni claves de firma.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Listar los proveedores externos a los que las personas pueden conectar sus cuentas, las aplicaciones autorizadas a usar temporalmente sus tokens y las personas conectadas, sin mostrar nunca secretos de cliente ni tokens.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Crear y revocar enlaces de un solo uso al portal de administración. Permiten al administrador de TI de una organización configurar SSO, dominios o sincronización de directorios sin tener una cuenta. Cada enlace nuevo se muestra una sola vez.',
    'no_roles_to_map_onto_yet_define_one_under_part1_part2_o_9b9aba76' => 'Aún no hay roles con los que establecer correspondencias. Define uno en :part1 :part2 o deja que una app declare los suyos.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'Nadie de esta organización ha creado una clave para alguna de sus aplicaciones. Cada persona crea sus claves en Mi cuenta, para una aplicación que haya activado las claves API de miembros en su configuración: :part1.',
    'nobody_is_signed_in_to_an_app_as_one_of_its_people_star_a41ae388' => 'Nadie ha iniciado sesión en una app como una de sus personas. Inicia una sesión desde la página de una persona en :part1 :part2.',
    'only_the_console_can_give_an_app_part1_not_a_management_e9037160' => 'Solo la consola puede conceder :part1 a una app, no una clave de gestión ni un agente que actúe en tu nombre. Concédelo en la consola, en la página Scopes de la app.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Solo se ofrecen las acciones que tú puedes realizar en :part1. Si más adelante pierdes un permiso, la clave también lo pierde.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Añade las claves de los indicadores de funcionalidad activados para la persona en la organización donde ha iniciado sesión como claim `feature_flags` en el token de acceso, el token de ID y UserInfo.',
    'puts_everything_userinfo_answers_for_the_app_s_scopes_e_db47369d' => 'Añade al token de ID todo lo que UserInfo devuelve para los ámbitos de la aplicación (correo electrónico, nombre, roles, permisos, organizaciones), para que la aplicación pueda omitir la llamada a UserInfo al iniciar sesión. Solo para una aplicación que envía `id_token_hint` por POST al cerrar sesión, o que no lo envía: un token en una URL queda escrito en los registros de acceso.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Incluye los ROLES de la persona en el token de ID con el nombre `groups`, que esperan Kubernetes, Grafana, Vault y muchas aplicaciones SaaS antiguas. En esta consola no hay un objeto llamado grupo. Crea un rol con el nombre que espera la aplicación y se incluirá en ese campo.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Leer el modo de Radar, sus reglas integradas y personalizadas, las listas de permitidos y bloqueados y el explorador de decisiones: por qué un inicio de sesión o registro se permitió, requirió verificación adicional o se bloqueó. Nunca se muestran direcciones IP ni de correo de una decisión.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Leer los eventos de auditoría enviados por tu aplicación y sus exportaciones, verificar la cadena de eventos de una organización y consultar los esquemas y las reglas de conservación aplicables.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Leer el esquema de autorización y sus tuplas y realizar comprobaciones de permisos y consultas de listas, como «¿puede este usuario editar este documento?» o «¿qué documentos puede ver?». Solo los permisos que necesita el backend de una aplicación para controlar el acceso.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Sustituye el esquema de autorización: los tipos de recurso y cómo se determina cada relación. Cambia de inmediato la respuesta a todas las comprobaciones de este entorno.',
    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Roles que se aplican en todo el entorno, en cada organización e incluso a quienes no pertenecen a ninguna. Las organizaciones nunca los ven.:part1 :part2',
    'sandbox_environment_for_testing_only_this_is_part1_your_4efdd306' => 'Entorno sandbox, solo para pruebas. Este :part1 es tu acceso de producción y no se envían correos reales.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'Scope «:part1» eliminado. Las apps que lo tenían lo conservan como scope introducido manualmente, que ya no da acceso a esta API.',
    'showing_the_first_part1_search_to_reach_the_rest_anythi_57d8cba9' => 'Se muestran los primeros :part1. Busca para encontrar el resto; todo lo que ya hayas marcado permanece en la lista.',
    'sms_allowed_country_count' => 'Aceptado como segundo factor en :count país.|Aceptado como segundo factor en :count países.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Una persona que :part1 nunca se envía: su contraseña es la de Cbox ID y el sistema anterior no interviene en ella.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Cuando una persona inicia sesión y es :part1, su correo y contraseña se envían a ese endpoint. Si responde afirmativamente, se crea aquí y no vuelve a enviarse.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Almacenar, rotar y revocar credenciales de servicios externos, y conceder o retirar a una aplicación el derecho a usarlas temporalmente. Esto no afecta a los ámbitos vault.manage / vault.lease del token propio de la aplicación.',
    'streamable_http_every_request_carries_part1_part2_a_man_6348600d' => 'Streamable HTTP. Cada solicitud incluye :part1 :part2, una clave de gestión de este entorno.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => '¿Tienes dudas sobre alguno de estos puntos? Cada página de la consola tiene un :part1 :part2 :part3 junto al título, con una explicación breve y un enlace a la guía completa.',
    'suspension_is_the_only_lever_here_and_it_is_reversible__9f87c506' => 'Aquí solo puedes suspender una organización o reactivarlo. Nada en esta página elimina una organización ni borra sus datos. La instalación también contiene entornos sin organización: la raíz de la plataforma y los entornos que hayan quedado sin asociar. Ambos se identifican claramente en :part1 :part2.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Esta página solo cambia la suspensión, que puede revertirse. Seleccionar y abrir un entorno solo cambia la vista de la consola, sin modificar ninguno de los entornos.',
    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'Los códigos SMS enviados a :part1 dejarán de funcionar. La aplicación de autenticación, las claves de acceso y los códigos de recuperación no se ven afectados. Si el número era el único segundo factor, la cuenta quedará protegida solo por la contraseña hasta que se configure otro factor.',
    'that_certificate_has_already_expired_part1_download_the_9adb4bed' => 'Ese certificado ya ha caducado (:part1). Descarga el certificado vigente de tu proveedor de identidad.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'No se puede usar ese favicon. Envía la imagen como una URI data: codificada en base64 (data:image/png;base64,…). No se aceptan URL de imágenes externas: cada visitante carga la imagen de la página de inicio de sesión, lo que revelaría información sobre los visitantes al servidor externo.',
    'that_is_a_lot_of_emails_try_again_in_part1_seconds_or_c_1e69af47' => 'Se han enviado muchos correos. Inténtalo de nuevo dentro de :part1 segundos o revisa mientras tanto la carpeta de spam.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'Ya está completada toda la lista. A partir de ahora volverás a la consola principalmente cuando la necesites. Conviene revisar dos secciones con regularidad: :part1 :part2 :part3 y :part4 :part5 :part6.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'No se puede usar ese logotipo. Envía la imagen como una URI data: codificada en base64 (data:image/png;base64,…). No se aceptan URL de imágenes externas: cada visitante carga la imagen de la página de inicio de sesión, lo que revelaría información sobre los visitantes al servidor externo.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'Los dominios de correo cuya propiedad han declarado tus organizaciones. Un dominio verificado envía a todas las personas con una dirección de ese dominio a la conexión de la organización: :part1 :part2. Cada dominio se verifica en la página de su organización.',
    'the_platform_s_own_environment_on_part1_how_every_organ_acd123ad' => 'El entorno propio de la plataforma en :part1: permite iniciar sesión en Cbox ID a todos los propietarios de organizaciones y operadores, además de acceder a las consolas de todos los entornos. Cualquier cambio se aplica a todos esos inicios de sesión.',
    'the_role_part1_cannot_be_held_in_this_organization_it_b_6fdeacd4' => 'El rol [:part1] no puede asignarse en esta organización: pertenece a otra organización o a una app que esta organización no puede utilizar.',
    'there_is_no_client_secret_to_paste_part1_expects_a_sign_574fe375' => 'No hay ningún secreto de cliente que pegar. :part1 espera una aserción firmada, que generamos con la clave anterior para cada inicio de sesión y renovamos mucho antes de que caduque.',
    'there_is_no_role_to_grant_yet_define_one_on_the_part1_p_ffe056a6' => 'Aún no hay ningún rol que asignar. Define uno en la página :part1 :part2 :part3 o deja que una app declare los suyos en su manifiesto.',
    'these_are_the_buttons_on_part1_how_every_organization_o_ca549807' => 'Estos son los botones de :part1 que usan los propietarios de organizaciones y los operadores para iniciar sesión en Cbox ID y, por tanto, en las consolas de todos los entornos, cuyos administradores usan cuentas de Cbox ID. Registra en cada proveedor la URI de redirección indicada. Está en :part2 :part3.',
    'these_buttons_are_for_the_people_who_sign_in_to_your_ap_580f5efd' => 'Estos botones son para las personas que acceden a tus apps, en las páginas de inicio de sesión de :part1 :part2. :part3',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Esa persona pasa a ser propietaria de :part1 y tú pasas a ser administrador. Solo el nuevo propietario puede devolverte la propiedad.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Esta aplicación tiene ámbitos de varias API: :part1 :part2. Un token corresponde a una API cada vez, por lo que la aplicación indica la que necesita con el parámetro :part3. Se rechazan las solicitudes de ámbitos de dos API a la vez.',
    'this_console_is_your_organization_its_projects_team_key_15ebbd0f' => 'Esta consola es tu organización: proyectos, equipo, claves y facturación. Los métodos de acceso a tus aplicaciones, incluida :part1, se configuran para cada entorno en su propia consola.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Esta credencial requiere la aprobación de una persona para realizar la acción, pero no hay ninguna registrada que pueda aprobarla. Ejecuta la acción desde la consola o crea allí una clave para que su propietario pueda aprobarla.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Esta instalación solo envía SMS a :part1, por lo que los números de :part2 no pueden recibir códigos hasta que se incluyan en CBOX_ID_SMS_ALLOWED_COUNTRIES.',
    'this_environment_s_issuer_discovery_and_jwks_are_served_06e9c844' => 'El emisor, el documento de descubrimiento y el JWKS de este entorno se sirven en :part1 :part2. Apunta el host a tu ingress y termina TLS allí.',
    'this_environment_s_own_issuer_what_an_sdk_discovers_fro_b00e706b' => 'El emisor propio de este entorno: desde donde un SDK realiza el descubrimiento y lo que contiene el claim :part1.',
    'this_person_is_the_only_owner_of_part1_organization_s_p_662dfa99' => 'Esta persona es la única propietaria de :part1 organizaciones: :part2. Transfiere la propiedad antes de borrarla.',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Los scopes introducidos manualmente (:part1) no tienen propietario: se transmiten tal cual, nunca con la audiencia de una API registrada.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'No se ha podido enviar el correo ahora porque esta instalación no puede contactar con su servidor de correo. Inténtalo de nuevo más tarde. Un administrador también puede confirmar tu dirección con `php artisan cbox-id:users:confirm-email`.',
    'we_have_sent_a_few_links_already_try_again_in_part1_sec_a84fe552' => 'Ya hemos enviado algunos enlaces. Inténtalo de nuevo dentro de :part1 segundos o revisa mientras tanto la carpeta de spam.',
    'we_sent_a_link_to_part1_your_first_environment_your_liv_9786541d' => 'Hemos enviado un enlace a :part1. En cuanto lo abras, se creará tu primer entorno: tu proveedor de identidad en producción, con inicio de sesión, usuarios y claves de firma propios. Después volverás directamente aquí. El enlace es válido durante 24 horas.',
    'which_of_its_actions_wait_for_a_person_the_agent_gets_a_e72df5dd' => 'Las acciones que esperan aprobación. El agente recibe una respuesta 202 con un código corto. Apruebas en tu teléfono o en :part1 :part2 y el agente repite la solicitud una sola vez.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Escribir y eliminar tuplas de relaciones: quién posee, edita o ve cada recurso de tu aplicación. El acceso se concede o revoca en cuanto se guarda el cambio.',
    'you_are_signed_in_part1_but_your_account_does_not_admin_1a2cb08a' => 'Has iniciado sesión :part1, pero tu cuenta no administra :part2. La consola de un entorno la pueden abrir los propietarios, administradores y desarrolladores de la organización al que pertenece.',
    'you_have_no_environment_to_open_yet_part1_part2_part3_t_3a10832d' => 'Aún no tienes ningún entorno que abrir.:part1 :part2 :part3 para crear uno o pide acceso a un propietario de la organización.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'Tu página de acceso tendrá un enlace «Crear una cuenta» y las apps podrán enviar a las personas directamente al registro con :part1.',
